#!/usr/bin/env node
// pqmp-requirements MCP server.
// Gives Claude Code structured access to the PQMP requirement set, the solution document (SRS),
// the portal analysis notes, and a requirement -> code/test traceability matrix.
// Data lives in analysis/ (generated by import-docs.js, maintained by the skills).
import fs from 'node:fs/promises';
import path from 'node:path';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';
import { REQUIREMENTS_FILE, SRS_FILE, TRACE_FILE, PORTAL_DIR, ROOT } from './paths.js';

const STATUSES = ['not-started', 'analysed', 'in-progress', 'implemented', 'tested', 'blocked', 'needs-approval'];

const readJson = async (file, fallback) => {
  try {
    return JSON.parse(await fs.readFile(file, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT' && fallback !== undefined) return fallback;
    if (err.code === 'ENOENT') throw new Error(`${path.relative(ROOT, file)} not found. Run "npm run import-docs" in tools/pqmp-mcp.`);
    throw err;
  }
};

const loadRequirements = () => readJson(REQUIREMENTS_FILE);
const loadSections = () => readJson(SRS_FILE);
const loadTrace = () => readJson(TRACE_FILE, {});

const STOP_WORDS = new Set('the and for with where from that this shall will should when user show case cases into able such'.split(' '));
const keywords = (text) =>
  [...new Set(text.toLowerCase().match(/[a-z][a-z0-9/]{2,}/g) ?? [])].filter((w) => !STOP_WORDS.has(w));

// TF-IDF style ranking (title counted twice); good enough for ~120 sections and keeps the server dependency-free.
function rankSections(sections, query, limit) {
  const terms = keywords(query);
  const docs = sections.map((s) => `${s.title} ${s.title} ${s.text}`.toLowerCase());
  const idf = Object.fromEntries(
    terms.map((t) => [t, Math.log((docs.length + 1) / (docs.filter((d) => d.includes(t)).length + 1))]),
  );
  return sections
    .map((s, i) => {
      const score = terms.reduce((sum, t) => sum + Math.log1p(docs[i].split(t).length - 1) * idf[t], 0);
      return { s, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((x) => x.s);
}

const text = (value) => ({ content: [{ type: 'text', text: typeof value === 'string' ? value : JSON.stringify(value, null, 2) }] });

const server = new McpServer({ name: 'pqmp-requirements', version: '0.1.0' });

server.registerTool(
  'list_requirements',
  {
    description:
      'List PQMP requirements with their traceability status. Filter by module name/ID prefix (e.g. "CREATE", "Case Creation"), status, or source ("task-list" | "prototype").',
    inputSchema: {
      module: z.string().optional(),
      status: z.enum(STATUSES).optional(),
      source: z.enum(['task-list', 'prototype']).optional(),
    },
  },
  async ({ module, status, source }) => {
    const [reqs, trace] = await Promise.all([loadRequirements(), loadTrace()]);
    const m = module?.toLowerCase();
    const rows = reqs
      .map((r) => ({ ...r, status: trace[r.id]?.status ?? 'not-started' }))
      .filter((r) => !m || r.module.toLowerCase().includes(m) || r.id.toLowerCase().startsWith(m))
      .filter((r) => !status || r.status === status)
      .filter((r) => !source || r.source === source)
      .map((r) => `${r.id} [${r.status}]${r.source === 'prototype' ? ' (prototype)' : ''} ${r.featureGroup}: ${r.requirement}`);
    return text(rows.length ? rows.join('\n') : 'No requirements match.');
  },
);

server.registerTool(
  'get_requirement',
  {
    description:
      'Get one requirement by ID (e.g. "CREATE-07") with its traceability record and the most relevant SRS sections, so implementation and tests follow the documented business rules.',
    inputSchema: { id: z.string(), sections: z.number().int().min(0).max(8).default(4) },
  },
  async ({ id, sections: limit }) => {
    const [reqs, srs, trace] = await Promise.all([loadRequirements(), loadSections(), loadTrace()]);
    const req = reqs.find((r) => r.id.toLowerCase() === id.toLowerCase());
    if (!req) return text(`Unknown requirement ${id}. Use list_requirements to see valid IDs.`);
    const related = rankSections(srs, `${req.module} ${req.featureGroup} ${req.requirement}`, limit);
    return text({ ...req, traceability: trace[req.id] ?? { status: 'not-started' }, relatedSrsSections: related });
  },
);

server.registerTool(
  'search_srs',
  {
    description: 'Full-text search over the PQMP solution document (SRS). Returns the best matching numbered sections.',
    inputSchema: { query: z.string(), limit: z.number().int().min(1).max(10).default(5) },
  },
  async ({ query, limit }) => {
    const hits = rankSections(await loadSections(), query, limit);
    return text(hits.length ? hits : 'No sections match.');
  },
);

server.registerTool(
  'get_srs_section',
  {
    description: 'Get SRS sections by number. "9.2" returns that section; "9" returns every 9.x section.',
    inputSchema: { number: z.string() },
  },
  async ({ number }) => {
    const srs = await loadSections();
    const hits = srs.filter((s) => s.number === number || s.number.startsWith(`${number}.`));
    return text(hits.length ? hits : `No section ${number}. Sections: ${[...new Set(srs.map((s) => s.number.split('.')[0]))].join(', ')}`);
  },
);

server.registerTool(
  'update_traceability',
  {
    description:
      'Record progress on a requirement: status, implementing files, test files, portal evidence, open questions. Fields given are merged into the existing record (arrays are unioned).',
    inputSchema: {
      id: z.string(),
      status: z.enum(STATUSES).optional(),
      implementation: z.array(z.string()).optional().describe('Repo-relative source files'),
      tests: z.array(z.string()).optional().describe('Repo-relative unit/E2E test files or Maestro flows'),
      portalEvidence: z.array(z.string()).optional().describe('analysis/portal/... notes or screenshots backing the behaviour'),
      openQuestions: z.array(z.string()).optional(),
      notes: z.string().optional(),
    },
  },
  async ({ id, ...patch }) => {
    const [reqs, trace] = await Promise.all([loadRequirements(), loadTrace()]);
    const req = reqs.find((r) => r.id.toLowerCase() === id.toLowerCase());
    if (!req) return text(`Unknown requirement ${id}.`);
    const prev = trace[req.id] ?? { status: 'not-started' };
    const next = { ...prev, updated: new Date().toISOString() };
    for (const [k, v] of Object.entries(patch)) {
      if (v === undefined) continue;
      next[k] = Array.isArray(v) ? [...new Set([...(prev[k] ?? []), ...v])] : v;
    }
    trace[req.id] = next;
    await fs.writeFile(TRACE_FILE, JSON.stringify(trace, null, 2) + '\n');
    return text({ id: req.id, ...next });
  },
);

server.registerTool(
  'coverage_report',
  {
    description: 'Summarise implementation/test coverage per module and list open questions across all requirements.',
    inputSchema: {},
  },
  async () => {
    const [reqs, trace] = await Promise.all([loadRequirements(), loadTrace()]);
    const byModule = {};
    const questions = [];
    for (const r of reqs) {
      const t = trace[r.id] ?? { status: 'not-started' };
      const key = r.id.split('-')[0];
      byModule[key] ??= { total: 0 };
      byModule[key].total += 1;
      byModule[key][t.status] = (byModule[key][t.status] ?? 0) + 1;
      for (const q of t.openQuestions ?? []) questions.push(`${r.id}: ${q}`);
    }
    const done = reqs.filter((r) => trace[r.id]?.status === 'tested').length;
    return text({ overall: `${done}/${reqs.length} tested`, byModule, openQuestions: questions });
  },
);

server.registerTool(
  'list_portal_analysis',
  {
    description: 'List the web-portal analysis notes captured by the analyze-portal skill (analysis/portal/), optionally returning one file\'s contents.',
    inputSchema: { file: z.string().optional().describe('File name inside analysis/portal to read') },
  },
  async ({ file }) => {
    if (file) {
      const target = path.resolve(PORTAL_DIR, file);
      if (!target.startsWith(PORTAL_DIR)) return text('File must be inside analysis/portal.');
      return text(await fs.readFile(target, 'utf8'));
    }
    const files = await fs.readdir(PORTAL_DIR).catch(() => []);
    return text(files.length ? files.join('\n') : 'No portal analysis yet. Run the analyze-portal skill.');
  },
);

await server.connect(new StdioServerTransport());
